<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
if(isset($_SESSION['admin'])&&time()-(int)($_SESSION['last_seen']??0)>1800)unset($_SESSION['admin']);
if(empty($_SESSION['admin'])){http_response_code(403);exit('Inicia sesión desde el panel de administración.');}
$_SESSION['last_seen']=time();
require_once dirname(__DIR__,2).'/app/AdminEmailWorkspace.php';
require_once dirname(__DIR__,2).'/app/BrevoSettings.php';
header("Content-Security-Policy: default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'; img-src 'self'; frame-src 'self'; frame-ancestors 'none'; form-action 'self'; base-uri 'self'");
header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');
$workspace=new AdminEmailWorkspace(private_storage_path('admin-email'));
$settings=BrevoSettings::load(private_storage_path('brevo'),(string)($config['app_key']??''));
$actor=(string)($config['admin_user']??'admin');$error='';$notice='';$tab=(string)($_GET['tab']??'individual');if(!in_array($tab,['individual','templates','history'],true))$tab='individual';
$contacts=[];$businessNames=[];$businessData=[];
try{
 $rows=db()->query('SELECT b.id,t.display_name,dt.display_name AS destination_name FROM businesses b JOIN business_translations t ON t.business_id=b.id AND t.locale="es" LEFT JOIN destination_translations dt ON dt.destination_id=b.destination_id AND dt.locale="es" ORDER BY t.display_name')->fetchAll(PDO::FETCH_ASSOC);
 foreach($rows as $row){$businessNames[(int)$row['id']]=$row['display_name'];$businessData[(int)$row['id']]=$row;}
 $sources=[['sql'=>"SELECT business_id,contact_value AS email FROM business_research_contacts WHERE channel='email' AND suppressed=0",'label'=>'Contacto comercial'],['sql'=>"SELECT business_id,contact_value AS email FROM business_contacts WHERE channel='email'",'label'=>'Correo del negocio'],['sql'=>"SELECT m.business_id,a.email FROM business_account_memberships m JOIN accounts a ON a.id=m.account_id WHERE m.status='active' AND a.status='active' AND a.email_verified_at IS NOT NULL",'label'=>'Cuenta responsable']];
 foreach($sources as $source){foreach(db()->query($source['sql'])->fetchAll(PDO::FETCH_ASSOC) as $row){$email=strtolower(trim($row['email']));$businessId=(int)$row['business_id'];if(!filter_var($email,FILTER_VALIDATE_EMAIL)||!isset($businessNames[$businessId]))continue;$key=hash('sha256',$businessId.'|'.$email);$contacts[$key]=['business_id'=>$businessId,'email'=>$email,'label'=>$businessNames[$businessId].' · '.$email.' · '.$source['label']];}}
}catch(PDOException){$error='No se pudieron consultar todos los canales. Revisa las estructuras de cuentas y contactos en Sistema.';}
$sender=['sender_email'=>(string)($settings['sender_email']??''),'sender_name'=>(string)($settings['sender_name']??'')];
$localPreview=!empty($config['local_test'])||preg_match('/^(127\.0\.0\.1|localhost|\[::1\])(?::[0-9]+)?$/D',(string)($_SERVER['HTTP_HOST']??''));
$edit=null;$message=null;$selectedTemplate=(string)($_GET['template']??$_POST['template_id']??'');$recipientKey=(string)($_POST['recipient']??'');
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  csrf();$action=(string)($_POST['action']??'');
  if($action==='preview_template'){
   if(strlen((string)($_POST['html']??''))>60000||strlen((string)($_POST['subject']??''))>250)throw new RuntimeException('El contenido supera el tamaño permitido.');
   $preview=AdminEmailWorkspace::render((string)($_POST['subject']??''),(string)($_POST['html']??''),['business_name'=>'Casa del Camino','recipient_name'=>'María','recipient_email'=>'ejemplo@example.invalid','destination_name'=>'Jericó','subscription_name'=>'Página Comercial','expiration_date'=>'31/12/2026']);
   header('Content-Type: application/json; charset=utf-8');echo json_encode($preview,JSON_THROW_ON_ERROR);exit;
  }
  if($action==='save_template'){$selectedTemplate=$workspace->saveTemplate($_POST,$actor);$tab='templates';$notice='Plantilla guardada. El HTML se validó y se quitaron elementos no admitidos.';}
  elseif($action==='preview'){
   if(($_POST['requested_reply']??'')!=='1')throw new RuntimeException('Confirma que se trata de una respuesta solicitada o comunicación de servicio. Para promociones, utiliza Campañas.');
   $contact=$contacts[$recipientKey]??null;if(!$contact)throw new RuntimeException('Selecciona un contacto existente válido.');
   $businessId=$contact['business_id'];$values=['business_name'=>$businessNames[$businessId],'destination_name'=>$businessData[$businessId]['destination_name']??'','recipient_name'=>'','subscription_name'=>'Gratis','expiration_date'=>''];
   $q=db()->prepare('SELECT a.display_name FROM business_account_memberships m JOIN accounts a ON a.id=m.account_id WHERE m.business_id=? AND m.status="active" AND LOWER(a.email)=? LIMIT 1');$q->execute([$businessId,$contact['email']]);$values['recipient_name']=(string)($q->fetchColumn()?:'');
   $q=db()->prepare('SELECT p.name,s.ends_at,s.status FROM business_subscriptions s JOIN subscription_plan_translations p ON p.plan_code=s.plan_code AND p.locale="es" WHERE s.business_id=? ORDER BY s.id DESC LIMIT 1');$q->execute([$businessId]);$sub=$q->fetch(PDO::FETCH_ASSOC);if($sub){$values['subscription_name']=$sub['name'];$values['expiration_date']=$sub['ends_at']??'';}
   $id=$workspace->prepare($selectedTemplate,$contact['email'],$values,$sender,$actor,$businessId,['subject'=>$_POST['subject_override']??'','html'=>$_POST['html_override']??'']);$_SESSION['admin_email_preview']=$id;header('Location: correos.php?message='.$id,true,303);exit;
  }elseif($action==='send'){
   $id=(string)($_POST['message_id']??'');if($localPreview)throw new RuntimeException('El envío real está deshabilitado en esta instancia local.');
   if(($_SESSION['admin_email_preview']??'')!==$id||($_POST['confirm_send']??'')!=='1')throw new RuntimeException('Abre la vista previa y confirma el destinatario y contenido antes de enviar.');
   $pending=$workspace->get('message',$id);$contactKey=hash('sha256',$pending['business_id'].'|'.$pending['email']);if(!isset($contacts[$contactKey]))throw new RuntimeException('El contacto cambió o ya no está disponible. Prepara una nueva vista previa.');
   $result=$workspace->send($id,$settings,$actor);unset($_SESSION['admin_email_preview']);header('Location: correos.php?message='.$id,true,303);exit;
  }else throw new RuntimeException('Acción no válida.');
 }
 if($selectedTemplate!=='')$edit=$workspace->get('template',$selectedTemplate);
 if(isset($_GET['message'])){$message=$workspace->get('message',(string)$_GET['message']);if($message['status']==='draft')$_SESSION['admin_email_preview']=$message['id'];}
}catch(Throwable $exception){http_response_code(400);$error=$exception instanceof PDOException?'No se pudo consultar el contexto del negocio. No se envió el correo.':$exception->getMessage();}
$templates=$workspace->all('template');$history=$workspace->all('message');
$states=['draft'=>'Borrador revisable','sending'=>'Envío iniciado; comprobar antes de reintentar','accepted'=>'Solicitud aceptada por Brevo; entrega no confirmada','rejected'=>'Rechazado por el proveedor','uncertain'=>'Resultado incierto; no reenviar automáticamente'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Plantillas y correos | Administración</title><?php require __DIR__.'/_theme.php'; ?></head><body class="portal-admin"><main class="wrap admin-page"><?php require __DIR__.'/_navigation.php'; ?><h1>Plantillas y correos</h1><p>Prepara respuestas individuales con contactos ya registrados y conserva su historial. Las promociones y los envíos a grupos se gestionan en <a href="campanas.php">Campañas</a>.</p>
<nav class="admin-workflow-tabs" aria-label="Correos"><a href="correos.php" <?=$tab==='individual'?'aria-current="page"':''?>>Correo individual</a><a href="correos.php?tab=templates" <?=$tab==='templates'?'aria-current="page"':''?>>Plantillas HTML</a><a href="correos.php?tab=history" <?=$tab==='history'?'aria-current="page"':''?>>Historial</a></nav>
<?php if($error):?><p class="notice" role="alert"><?=esc($error)?></p><?php endif ?><?php if($notice):?><p class="notice" role="status"><?=esc($notice)?></p><?php endif ?>
<?php if($message):?><section class="destination-editor"><h2>Vista previa del correo</h2><dl><dt>Negocio</dt><dd><?=esc($businessNames[$message['business_id']]??'')?></dd><dt>Destinatario</dt><dd><?=esc($message['email'])?></dd><dt>Remitente</dt><dd><?=esc($message['sender']['sender_name'].' · '.$message['sender']['sender_email'])?></dd><dt>Asunto</dt><dd><?=esc($message['content']['subject'])?></dd><dt>Estado</dt><dd><?=esc($states[$message['status']]??$message['status'])?></dd></dl><iframe title="Vista previa HTML del correo" sandbox="" referrerpolicy="no-referrer" class="admin-email-preview" srcdoc="<?=esc($message['content']['html'])?>"></iframe><details><summary>Versión de texto</summary><pre class="admin-email-text"><?=esc($message['content']['text'])?></pre></details>
<?php if($message['status']==='draft'):?><?php if($localPreview):?><p class="notice">Modo local: puedes revisar el correo, pero el envío real está bloqueado.</p><?php else:?><form method="post" class="campaign-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="send"><input type="hidden" name="message_id" value="<?=esc($message['id'])?>"><label><input type="checkbox" name="confirm_send" value="1" required> Confirmo enviar este contenido a <?=esc($message['email'])?>.</label><button class="pill">Enviar este correo</button></form><?php endif ?><a href="correos.php?template=<?=esc($message['template_id'])?>">Preparar otro borrador</a><?php endif ?></section>
<?php elseif($tab==='templates'):?><section class="destination-editor"><h2><?=esc($edit?'Editar plantilla':'Crear plantilla HTML')?></h2><p>Variables: <code>{{business_name}}</code>, <code>{{recipient_name}}</code>, <code>{{recipient_email}}</code>, <code>{{destination_name}}</code>, <code>{{subscription_name}}</code>, <code>{{expiration_date}}</code>. Un dato no registrado se deja vacío. Se admite HTML básico y enlaces HTTPS; scripts, estilos e imágenes externas se retiran.</p><form method="post" class="campaign-form" data-template-editor><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="save_template"><input type="hidden" name="template_id" value="<?=esc($edit['id']??'')?>"><label>Nombre<input name="name" required maxlength="180" value="<?=esc($_POST['name']??$edit['name']??'')?>"></label><label>Asunto<input name="subject" required maxlength="250" value="<?=esc($_POST['subject']??$edit['subject']??'')?>"></label><label>Contenido HTML<textarea name="html" required rows="12" maxlength="60000"><?=esc($_POST['html']??$edit['html']??'<p>Hola {{recipient_name}},</p><p>Te escribimos sobre {{business_name}} en {{destination_name}}.</p><p>Explorando Lugares</p>')?></textarea></label><button class="pill">Guardar plantilla</button></form><section aria-label="Vista previa de la plantilla"><h3>Así se verá el correo</h3><p>La vista se actualiza al escribir y usa datos de ejemplo. No guarda ni envía correos. El resultado aplica las mismas reglas de HTML que el envío.</p><p><strong>Asunto:</strong> <span data-template-subject></span></p><p data-template-preview-status role="status"></p><iframe title="Vista previa de la plantilla" sandbox="" referrerpolicy="no-referrer" class="admin-email-preview" data-template-preview></iframe></section></section><section><h2>Plantillas guardadas</h2><?php foreach($templates as $template):?><p><strong><?=esc($template['name'])?></strong> · versión <?=$template['revision']?> <a class="pill light compact" href="correos.php?tab=templates&amp;template=<?=esc($template['id'])?>">Editar</a> <a class="pill light compact" href="correos.php?template=<?=esc($template['id'])?>">Usar en correo individual</a></p><?php endforeach ?><?php if(!$templates):?><p>Todavía no hay plantillas guardadas.</p><?php endif ?></section>
<?php elseif($tab==='history'):?><h2>Historial de correos individuales</h2><form method="get" class="business-filter-bar"><input type="hidden" name="tab" value="history"><label>Negocio<select name="business_id"><option value="">Todos</option><?php foreach($businessNames as $businessId=>$name):?><option value="<?=$businessId?>" <?=((int)($_GET['business_id']??0)===$businessId)?'selected':''?>><?=esc($name)?></option><?php endforeach ?></select></label><button class="pill compact">Consultar</button></form><div class="destination-admin-table"><table><thead><tr><th>Negocio y destinatario</th><th>Asunto</th><th>Estado</th><th>Fecha</th><th></th></tr></thead><tbody><?php foreach($history as $entry):if(!empty($_GET['business_id'])&&(int)$_GET['business_id']!==$entry['business_id'])continue;?><tr><td><?=esc($businessNames[$entry['business_id']]??'')?> · <?=esc($entry['email'])?></td><td><?=esc($entry['content']['subject'])?></td><td><?=esc($states[$entry['status']]??$entry['status'])?></td><td><?=esc($entry['updated_at'])?></td><td><a href="correos.php?message=<?=esc($entry['id'])?>">Ver correo</a></td></tr><?php endforeach ?></tbody></table></div>
<?php else:?><section class="destination-editor"><h2>Preparar correo individual</h2><?php if(!$templates):?><p>Primero <a class="pill compact" href="correos.php?tab=templates">crea una plantilla HTML</a>.</p><?php else:?><form method="post" class="campaign-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="preview"><label>Plantilla<select name="template_id" required><?php foreach($templates as $template):?><option value="<?=esc($template['id'])?>" <?=$selectedTemplate===$template['id']?'selected':''?>><?=esc($template['name'])?></option><?php endforeach ?></select></label><label>Negocio y destinatario<select name="recipient" required><option value="">Selecciona un contacto</option><?php foreach($contacts as $key=>$contact):if(!empty($_GET['business_id'])&&(int)$_GET['business_id']!==$contact['business_id'])continue;?><option value="<?=esc($key)?>" <?=$recipientKey===$key?'selected':''?>><?=esc($contact['label'])?></option><?php endforeach ?></select></label><details><summary>Ajustar el contenido solo para este correo</summary><label>Asunto alternativo (opcional)<input name="subject_override" maxlength="250" value="<?=esc($_POST['subject_override']??'')?>"></label><label>HTML alternativo (opcional)<textarea name="html_override" rows="8" maxlength="60000"><?=esc($_POST['html_override']??'')?></textarea></label><p>Deja los campos vacíos para usar la plantilla. Los ajustes no modifican la plantilla guardada y se mostrarán antes de confirmar.</p></details><label><input type="checkbox" name="requested_reply" value="1" required> Es una respuesta solicitada o comunicación de servicio. No inscribe al contacto en campañas.</label><button class="pill">Completar datos y ver correo</button></form><?php endif ?></section><?php endif ?></main><script src="<?=esc(admin_asset('admin-email-preview.js'))?>" defer></script></body></html>
